-- Squashed baseline schema (2026-08-04).
--
-- Generated by replaying the full ledgered migration history 0001-init.sql
-- through 0144-drop-jobs-observability-columns.sql (145 files, final
-- pre-squash main commit 63616db6) against a fresh local D1 database and
-- dumping schema plus migration-seeded platform rows (RBAC roles and
-- permissions, the system/user email graph authority markers, and the
-- d1_storage_reconcile_cursor row).
--
-- The pre-squash history remains available in Git history at tag-time; the
-- d1_migrations bookkeeping reset that pairs with this file lives in
-- tools/ci/reset-migration-bookkeeping.ts and is invoked by the preview and
-- production deploy workflows before "wrangler d1 migrations apply".
--
-- This filename is deliberately NOT 0001-init.sql: a pre-squash checkout
-- deploying against post-squash bookkeeping must fail fast on its first
-- CREATE TABLE instead of silently re-applying history.

PRAGMA defer_foreign_keys = TRUE;

CREATE TABLE password_resets (
	id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
	user_id INTEGER NOT NULL,
	token_hash TEXT NOT NULL UNIQUE,
	expires_at INTEGER NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE value_buckets (
	id TEXT PRIMARY KEY NOT NULL,
	user_id TEXT NOT NULL,
	scope TEXT NOT NULL CHECK (scope IN ('session', 'app', 'user')),
	binding_key TEXT NOT NULL,
	expires_at TEXT,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	UNIQUE(user_id, scope, binding_key)
);
CREATE TABLE value_entries (
	bucket_id TEXT NOT NULL,
	name TEXT NOT NULL,
	description TEXT NOT NULL DEFAULT '',
	value TEXT NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	PRIMARY KEY (bucket_id, name),
	FOREIGN KEY (bucket_id) REFERENCES value_buckets(id) ON DELETE CASCADE
);
CREATE TABLE mcp_user_server_instructions (
	user_id TEXT PRIMARY KEY NOT NULL,
	instructions TEXT NOT NULL,
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
CREATE TABLE mcp_memories (
	id TEXT PRIMARY KEY NOT NULL,
	user_id TEXT NOT NULL,
	category TEXT,
	status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'deleted', 'archived')),
	subject TEXT NOT NULL,
	summary TEXT NOT NULL,
	details TEXT NOT NULL DEFAULT '',
	tags_json TEXT NOT NULL DEFAULT '[]',
	dedupe_key TEXT,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	last_accessed_at TEXT,
	deleted_at TEXT
, source_uris_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE mcp_memory_conversation_suppressions (
	user_id TEXT NOT NULL,
	conversation_id TEXT NOT NULL,
	memory_id TEXT NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	last_seen_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	expires_at TEXT NOT NULL,
	PRIMARY KEY (user_id, conversation_id, memory_id),
	FOREIGN KEY (memory_id) REFERENCES mcp_memories(id) ON DELETE CASCADE
);
CREATE TABLE entity_sources (
	id TEXT PRIMARY KEY,
	user_id TEXT NOT NULL,
	entity_kind TEXT NOT NULL,
	entity_id TEXT NOT NULL,
	repo_id TEXT NOT NULL,
	published_commit TEXT,
	indexed_commit TEXT,
	manifest_path TEXT NOT NULL DEFAULT 'kody.json',
	source_root TEXT NOT NULL DEFAULT '/',
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL
, last_external_check_at TEXT, external_check_until TEXT);
CREATE TABLE IF NOT EXISTS "jobs" (
	id TEXT PRIMARY KEY NOT NULL,
	user_id TEXT NOT NULL,
	name TEXT NOT NULL,
	source_id TEXT NOT NULL,
	published_commit TEXT,
	repo_check_policy_json TEXT,
	storage_id TEXT NOT NULL,
	params_json TEXT,
	schedule_json TEXT NOT NULL,
	timezone TEXT NOT NULL,
	enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
	kill_switch_enabled INTEGER NOT NULL DEFAULT 0 CHECK (kill_switch_enabled IN (0, 1)),
	caller_context_json TEXT NOT NULL,
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL,
	last_run_at TEXT,
	last_run_status TEXT,
	next_run_at TEXT NOT NULL,
	preserved INTEGER NOT NULL DEFAULT 0
	CHECK (preserved IN (0, 1)), claim_token TEXT, running_since TEXT, lease_expires_at TEXT, claimed_scheduled_for TEXT, retry_scheduled_for TEXT, retry_count INTEGER NOT NULL DEFAULT 0, last_completed_scheduled_for TEXT, expires_at TEXT);
CREATE TABLE saved_packages (
	id TEXT PRIMARY KEY NOT NULL,
	user_id TEXT NOT NULL,
	name TEXT NOT NULL,
	kody_id TEXT NOT NULL,
	description TEXT NOT NULL,
	tags_json TEXT NOT NULL DEFAULT '[]',
	search_text TEXT,
	source_id TEXT NOT NULL,
	has_app INTEGER NOT NULL DEFAULT 0 CHECK (has_app IN (0, 1)),
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
, hidden INTEGER NOT NULL DEFAULT 0 CHECK (hidden IN (0, 1)), is_private INTEGER NOT NULL DEFAULT 1 CHECK (is_private IN (0, 1)));
CREATE TABLE published_bundle_artifacts (
	id TEXT PRIMARY KEY,
	user_id TEXT NOT NULL,
	source_id TEXT NOT NULL,
	published_commit TEXT NOT NULL,
	artifact_kind TEXT NOT NULL,
	artifact_name TEXT,
	entry_point TEXT NOT NULL,
	kv_key TEXT NOT NULL,
	dependencies_json TEXT NOT NULL DEFAULT '[]',
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL
);
CREATE TABLE archived_job_artifacts (
	id TEXT PRIMARY KEY,
	job_id TEXT NOT NULL UNIQUE,
	user_id TEXT NOT NULL,
	source_id TEXT NOT NULL,
	published_commit TEXT NOT NULL,
	storage_id TEXT NOT NULL,
	retain_until TEXT NOT NULL,
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL
);
CREATE TABLE package_invocation_tokens (
	id TEXT PRIMARY KEY,
	user_id TEXT NOT NULL,
	name TEXT NOT NULL,
	token_hash TEXT NOT NULL UNIQUE,
	email TEXT NOT NULL,
	display_name TEXT NOT NULL,
	package_ids_json TEXT NOT NULL DEFAULT '[]',
	package_kody_ids_json TEXT NOT NULL DEFAULT '[]',
	export_names_json TEXT NOT NULL DEFAULT '[]',
	sources_json TEXT NOT NULL DEFAULT '[]',
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL,
	last_used_at TEXT,
	revoked_at TEXT
);
CREATE TABLE IF NOT EXISTS "email_inboxes" (
	id TEXT PRIMARY KEY,
	user_id TEXT NOT NULL,
	package_id TEXT,
	name TEXT NOT NULL,
	description TEXT NOT NULL DEFAULT '',
	enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "email_inbox_addresses" (
	id TEXT PRIMARY KEY,
	inbox_id TEXT NOT NULL,
	user_id TEXT NOT NULL,
	address TEXT NOT NULL,
	local_part TEXT NOT NULL,
	domain TEXT NOT NULL,
	enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL,
	FOREIGN KEY (inbox_id) REFERENCES "email_inboxes"(id) ON DELETE CASCADE
);
CREATE TABLE repo_sessions (
	id TEXT PRIMARY KEY,
	user_id TEXT NOT NULL,
	source_id TEXT NOT NULL,
	source_repo_id TEXT NOT NULL,
	session_branch TEXT NOT NULL,
	source_branch TEXT NOT NULL,
	base_commit TEXT NOT NULL,
	source_root TEXT NOT NULL DEFAULT '/',
	conversation_id TEXT,
	status TEXT NOT NULL DEFAULT 'active',
	expires_at TEXT,
	last_checkpoint_at TEXT,
	last_checkpoint_commit TEXT,
	last_check_run_id TEXT,
	last_check_tree_hash TEXT,
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL
);
CREATE TABLE roles (
	id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
	name TEXT NOT NULL UNIQUE,
	description TEXT NOT NULL DEFAULT '',
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
