CREATE TABLE user_roles (
	user_id INTEGER NOT NULL,
	role_id INTEGER NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	PRIMARY KEY (user_id, role_id),
	FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
	FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE
);
CREATE TABLE community_listings (
	id TEXT PRIMARY KEY NOT NULL,
	owner_user_id TEXT NOT NULL,
	package_id TEXT NOT NULL,
	source_id TEXT NOT NULL,
	kody_id TEXT NOT NULL,
	name TEXT NOT NULL,
	description TEXT NOT NULL,
	tags_json TEXT NOT NULL DEFAULT '[]',
	search_text TEXT,
	readme_content TEXT,
	license TEXT NOT NULL,
	pinned_commit TEXT NOT NULL,
	status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'delisted')),
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	published_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
, trusted_commit TEXT, trusted_by_user_id TEXT, trusted_at TEXT, featured_at TEXT);
CREATE TABLE community_ratings (
	id TEXT PRIMARY KEY NOT NULL,
	listing_id TEXT NOT NULL,
	user_id TEXT NOT NULL,
	stars INTEGER NOT NULL CHECK (stars BETWEEN 1 AND 5),
	adaptation_effort INTEGER NOT NULL CHECK (adaptation_effort BETWEEN 1 AND 5),
	note TEXT,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
CREATE TABLE community_reports (
	id TEXT PRIMARY KEY NOT NULL,
	listing_id TEXT NOT NULL,
	listing_name TEXT NOT NULL,
	listing_owner_user_id TEXT NOT NULL,
	reporter_user_id TEXT NOT NULL,
	reason TEXT NOT NULL,
	status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved', 'dismissed')),
	resolved_by_user_id TEXT,
	resolved_at TEXT,
	resolution_note TEXT,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
CREATE TABLE community_bans (
	user_id TEXT PRIMARY KEY NOT NULL,
	banned_by_user_id TEXT NOT NULL,
	reason TEXT NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
CREATE TABLE email_verifications (
	id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
	user_id INTEGER NOT NULL,
	token_hash TEXT NOT NULL UNIQUE,
	expires_at INTEGER NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE usage_rollups (
	user_id TEXT NOT NULL,
	metric TEXT NOT NULL,
	month TEXT NOT NULL,
	event_count INTEGER NOT NULL DEFAULT 0,
	error_count INTEGER NOT NULL DEFAULT 0,
	total_duration_ms INTEGER NOT NULL DEFAULT 0,
	total_cpu_ms INTEGER NOT NULL DEFAULT 0,
	total_bytes INTEGER NOT NULL DEFAULT 0,
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	PRIMARY KEY (user_id, metric, month)
);
CREATE TABLE IF NOT EXISTS "remote_connector_settings" (
	id TEXT PRIMARY KEY NOT NULL,
	user_id TEXT NOT NULL,
	instance_id TEXT NOT NULL,
	enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
	attached INTEGER NOT NULL DEFAULT 1 CHECK (attached IN (0, 1)),
	encrypted_shared_secret TEXT,
	created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
	updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
	UNIQUE(user_id, instance_id)
);
CREATE TABLE system_email_daily_counters (
	local_part TEXT NOT NULL,
	day TEXT NOT NULL,
	count INTEGER NOT NULL DEFAULT 0,
	updated_at TEXT NOT NULL, operation_token TEXT,
	PRIMARY KEY (local_part, day)
);
CREATE TABLE pending_email_changes (
	id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
	user_id INTEGER NOT NULL,
	new_email TEXT NOT NULL,
	token_hash TEXT NOT NULL UNIQUE,
	expires_at INTEGER NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE mcp_server_settings (
	id TEXT PRIMARY KEY NOT NULL,
	user_id TEXT NOT NULL,
	name TEXT NOT NULL,
	url TEXT NOT NULL,
	enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
	created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
	updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
	UNIQUE(user_id, name)
);
CREATE TABLE verifications (
	id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
	type TEXT NOT NULL,
	target TEXT NOT NULL,
	secret TEXT NOT NULL,
	algorithm TEXT NOT NULL,
	digits INTEGER NOT NULL,
	period INTEGER NOT NULL,
	char_set TEXT NOT NULL,
	expires_at INTEGER,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	UNIQUE (target, type)
);
CREATE TABLE passkeys (
	id TEXT PRIMARY KEY NOT NULL,
	aaguid TEXT NOT NULL,
	public_key TEXT NOT NULL,
	user_id INTEGER NOT NULL,
	webauthn_user_handle TEXT NOT NULL,
	counter INTEGER NOT NULL DEFAULT 0,
	device_type TEXT NOT NULL,
	backed_up INTEGER NOT NULL DEFAULT 0,
	transports TEXT,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), name TEXT NOT NULL DEFAULT '', last_used_at TEXT,
	FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE oauth_connections (
	id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
	provider_name TEXT NOT NULL,
	provider_id TEXT NOT NULL,
	user_id INTEGER NOT NULL,
	provider_display_name TEXT,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	UNIQUE (provider_name, provider_id),
	FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "secret_buckets" (
	id TEXT PRIMARY KEY NOT NULL,
	user_id TEXT NOT NULL,
	scope TEXT NOT NULL CHECK (scope IN ('session', 'package', 'user')),
	binding_key TEXT NOT NULL,
	expires_at TEXT,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	UNIQUE(user_id, scope, binding_key)
);
CREATE TABLE IF NOT EXISTS "secret_entries" (
	bucket_id TEXT NOT NULL,
	name TEXT NOT NULL,
	description TEXT NOT NULL DEFAULT '',
	encrypted_value TEXT NOT NULL,
	allowed_hosts TEXT NOT NULL DEFAULT '[]',
	allowed_capabilities TEXT NOT NULL DEFAULT '[]',
	lookup_hash TEXT,
	allowed_packages TEXT NOT NULL DEFAULT '[]',
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	PRIMARY KEY (bucket_id, name),
	FOREIGN KEY (bucket_id) REFERENCES "secret_buckets"(id) ON DELETE CASCADE
);
CREATE TABLE feature_flags (
	key TEXT PRIMARY KEY NOT NULL,
	enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
	rollout_percent INTEGER CHECK (rollout_percent BETWEEN 0 AND 100),
	note TEXT NOT NULL DEFAULT '',
	updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
CREATE TABLE feature_flag_user_overrides (
	flag_key TEXT NOT NULL,
	user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
	enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)),
	updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
	updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	PRIMARY KEY (flag_key, user_id)
);
CREATE TABLE user_follows (
	follower_user_id TEXT NOT NULL,
	followee_user_id TEXT NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	PRIMARY KEY (follower_user_id, followee_user_id)
);
CREATE TABLE community_stars (
	listing_id TEXT NOT NULL,
	user_id TEXT NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	PRIMARY KEY (listing_id, user_id)
);
CREATE TABLE community_activity_events (
	id TEXT PRIMARY KEY NOT NULL,
	actor_user_id TEXT NOT NULL,
	event_type TEXT NOT NULL CHECK (event_type IN ('listing_published', 'listing_updated')),
	listing_id TEXT NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
CREATE TABLE IF NOT EXISTS "community_forks" (
	id TEXT PRIMARY KEY NOT NULL,
	listing_id TEXT NOT NULL,
	forker_user_id TEXT NOT NULL,
	origin_commit TEXT NOT NULL,
	forked_package_id TEXT NOT NULL,
	forked_source_id TEXT NOT NULL,
	target_kody_id TEXT NOT NULL,
	listing_name TEXT,
	listing_kody_id TEXT,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
, adopted_at TEXT, adoption_note TEXT, actor TEXT
CHECK (actor IS NULL OR actor IN ('human', 'agent')));
CREATE TABLE package_scope_grants (
	scope_owner_user_id TEXT NOT NULL,
	grantee_user_id TEXT NOT NULL,
	created_by_user_id TEXT NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	PRIMARY KEY (scope_owner_user_id, grantee_user_id),
	CHECK (scope_owner_user_id != grantee_user_id)
);
CREATE TABLE agent_package_conversation_uses (
	user_id TEXT NOT NULL,
	package_id TEXT NOT NULL,
	conversation_id TEXT NOT NULL,
	first_used_at TEXT NOT NULL,
	last_used_at TEXT NOT NULL,
	PRIMARY KEY (user_id, package_id, conversation_id)
);
CREATE TABLE IF NOT EXISTS "email_sender_identities" (
	id TEXT PRIMARY KEY,
	user_id TEXT NOT NULL,
	package_id TEXT,
	email TEXT NOT NULL,
	domain TEXT,
	display_name TEXT NOT NULL DEFAULT '',
	status TEXT NOT NULL CHECK (status IN ('verified')),
	verified_at TEXT,
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL
);
CREATE TABLE mcp_agent_sessions (
	do_id TEXT PRIMARY KEY NOT NULL,
	user_id TEXT NOT NULL,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
CREATE TABLE account_write_lease_repairs (
	id TEXT PRIMARY KEY NOT NULL,
	target_user_id TEXT NOT NULL,
	lease_token TEXT NOT NULL,
	lease_holder TEXT NOT NULL,
	lease_acquired_at TEXT NOT NULL,
	repaired_by_user_id TEXT NOT NULL,
	reason TEXT NOT NULL,
	created_at TEXT NOT NULL
);
CREATE TABLE webhook_endpoints (
	id TEXT PRIMARY KEY,
	user_id TEXT NOT NULL,
	package_id TEXT NOT NULL,
	webhook_name TEXT NOT NULL,
	url_secret_hash TEXT NOT NULL,
	enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
	created_at TEXT NOT NULL,
	rotated_at TEXT NOT NULL
);
CREATE TABLE stripe_webhook_events (
	event_id TEXT PRIMARY KEY NOT NULL,
	event_type TEXT NOT NULL,
	processed_at TEXT NOT NULL
);
CREATE TABLE package_service_states (
	user_id TEXT NOT NULL,
	package_id TEXT NOT NULL,
	service_name TEXT NOT NULL,
	status TEXT NOT NULL CHECK (status IN ('running', 'idle', 'stopped', 'error')),
	started_at TEXT,
	updated_at TEXT NOT NULL,
	PRIMARY KEY (user_id, package_id, service_name)
);
CREATE TABLE user_oauth_apps (
	user_id TEXT NOT NULL,
	slug TEXT NOT NULL,
	provider TEXT NOT NULL,
	label TEXT,
	client_id TEXT NOT NULL,
	client_secret_secret_name TEXT,
	token_url TEXT NOT NULL,
	authorize_url TEXT,
	api_base_url TEXT,
	flow TEXT NOT NULL CHECK (flow IN ('pkce', 'confidential')),
	use_pkce INTEGER CHECK (use_pkce IN (0, 1)),
	token_exchange_style TEXT CHECK (token_exchange_style IN ('form', 'basic-json', 'basic-form')),
	scope_separator TEXT,
	extra_authorize_params_json TEXT NOT NULL DEFAULT '{}',
	created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
	updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
	PRIMARY KEY (user_id, slug)
);
CREATE TABLE user_integrations (
	user_id TEXT NOT NULL,
	name TEXT NOT NULL,
	app_slug TEXT NOT NULL,
	account_label TEXT,
	description TEXT NOT NULL DEFAULT '',
	scopes_json TEXT NOT NULL DEFAULT '[]',
	required_hosts_json TEXT NOT NULL DEFAULT '[]',
	access_token_secret_name TEXT NOT NULL,
	refresh_token_secret_name TEXT,
	connected_at TEXT,
	token_refreshed_at TEXT,
	created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
	updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
	PRIMARY KEY (user_id, name),
	FOREIGN KEY (user_id, app_slug) REFERENCES user_oauth_apps(user_id, slug) ON DELETE RESTRICT
);
CREATE TABLE user_openapi_bindings (
	user_id TEXT NOT NULL,
	name TEXT NOT NULL,
	spec_url TEXT NOT NULL,
	api_base_url TEXT NOT NULL,
	description TEXT,
	auth_json TEXT NOT NULL,
	selection_json TEXT NOT NULL,
	include_destructive INTEGER NOT NULL DEFAULT 0 CHECK (include_destructive IN (0, 1)),
	spec_title TEXT,
	spec_version TEXT,
	created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
	updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
	PRIMARY KEY (user_id, name)
);
CREATE TABLE user_openapi_binding_operations (
	user_id TEXT NOT NULL,
	binding_name TEXT NOT NULL,
	slug TEXT NOT NULL,
	operation_json TEXT NOT NULL,
	PRIMARY KEY (user_id, binding_name, slug),
	FOREIGN KEY (user_id, binding_name) REFERENCES user_openapi_bindings(user_id, name) ON DELETE CASCADE
);
CREATE TABLE email_sender_rules (
	id TEXT PRIMARY KEY,
	user_id TEXT NOT NULL,
	kind TEXT NOT NULL CHECK (kind IN ('address', 'domain')),
	value TEXT NOT NULL,
	effect TEXT NOT NULL CHECK (effect IN ('allow', 'block', 'quarantine')),
	note TEXT NOT NULL DEFAULT '',
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL
);
CREATE TABLE package_codemod_runs (
	id TEXT PRIMARY KEY NOT NULL,
	codemod_id TEXT NOT NULL,
	mode TEXT NOT NULL,
	scope_user_id TEXT,
	initiated_by_user_id TEXT NOT NULL,
	filters_json TEXT NOT NULL DEFAULT '{}',
	status TEXT NOT NULL,
	revert_of_run_id TEXT,
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL
);
CREATE TABLE package_codemod_run_items (
	id TEXT PRIMARY KEY NOT NULL,
	run_id TEXT NOT NULL,
	user_id TEXT NOT NULL,
	package_id TEXT NOT NULL,
	kody_id TEXT NOT NULL,
	status TEXT NOT NULL,
	before_commit TEXT,
	after_commit TEXT,
	changed_paths_json TEXT NOT NULL DEFAULT '[]',
	findings_json TEXT NOT NULL DEFAULT '[]',
	check_summary_json TEXT,
	error TEXT,
	revert_snapshot_key TEXT,
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "invites" (
	code TEXT PRIMARY KEY NOT NULL,
	created_by INTEGER,
	note TEXT NOT NULL DEFAULT '',
	max_uses INTEGER NOT NULL DEFAULT 1 CHECK (max_uses > 0),
	use_count INTEGER NOT NULL DEFAULT 0 CHECK (use_count >= 0),
	expires_at TEXT,
	revoked_at TEXT,
	created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	plan TEXT NOT NULL DEFAULT 'free' CHECK (
		plan IN ('free', 'partner', 'pro', 'max')
	),
	FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE IF NOT EXISTS "platform_feedback" (
	id TEXT PRIMARY KEY NOT NULL,
	submitter_user_id TEXT NOT NULL,
	category TEXT NOT NULL CHECK (
		category IN ('friction', 'bug', 'experience', 'suggestion', 'other')
	),
	summary TEXT NOT NULL CHECK (
		length(summary) BETWEEN 1 AND 200
	),
	details TEXT NOT NULL CHECK (
		length(details) BETWEEN 1 AND 8000
	),
	status TEXT NOT NULL DEFAULT 'open' CHECK (
		status IN ('open', 'triaged', 'resolved', 'dismissed')
	),
	reviewed_by_user_id TEXT,
	reviewed_at TEXT,
	admin_note TEXT CHECK (
		admin_note IS NULL OR length(admin_note) <= 2000
	),
	revision INTEGER NOT NULL DEFAULT 0,
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL,
	submitter_username TEXT NOT NULL,
	submitter_email TEXT NOT NULL
);
CREATE TABLE feature_flag_exposure_rollups (
	flag_key TEXT NOT NULL,
	user_id TEXT NOT NULL,
	day TEXT NOT NULL,
	enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)),
	source TEXT NOT NULL,
	exposure_count INTEGER NOT NULL DEFAULT 0,
	updated_at TEXT NOT NULL,
	PRIMARY KEY (flag_key, user_id, day, enabled, source)
);
CREATE TABLE IF NOT EXISTS "user_storage_buckets" (
	user_id TEXT NOT NULL,
	storage_id TEXT NOT NULL,
	kind TEXT NOT NULL CHECK (
		kind IN ('job', 'package', 'service', 'execute', 'unknown')
	),
	created_at TEXT NOT NULL,
	last_seen_at TEXT NOT NULL,
	estimated_bytes INTEGER,
	estimated_bytes_updated_at TEXT,
	PRIMARY KEY (user_id, storage_id)
);
CREATE TABLE system_email_threads (
	id TEXT PRIMARY KEY,
	inbox_id TEXT,
	subject_normalized TEXT NOT NULL DEFAULT '',
	root_message_id_header TEXT,
	last_message_at TEXT NOT NULL,
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL,
	FOREIGN KEY (inbox_id) REFERENCES email_inboxes(id) ON DELETE SET NULL
);
CREATE TABLE system_email_messages (
	id TEXT PRIMARY KEY,
	direction TEXT NOT NULL CHECK (direction IN ('inbound', 'outbound')),
	inbox_id TEXT,
	thread_id TEXT,
	sender_identity_id TEXT,
	from_address TEXT NOT NULL,
	envelope_from TEXT,
	to_addresses_json TEXT NOT NULL DEFAULT '[]',
	cc_addresses_json TEXT NOT NULL DEFAULT '[]',
	bcc_addresses_json TEXT NOT NULL DEFAULT '[]',
	reply_to_addresses_json TEXT NOT NULL DEFAULT '[]',
	subject TEXT NOT NULL DEFAULT '',
	message_id_header TEXT,
	in_reply_to_header TEXT,
	references_json TEXT NOT NULL DEFAULT '[]',
	headers_json TEXT NOT NULL DEFAULT '{}',
	auth_results TEXT,
	text_body TEXT,
	html_body TEXT,
	raw_size INTEGER NOT NULL DEFAULT 0,
	processing_status TEXT NOT NULL CHECK (
		processing_status IN ('stored', 'sent', 'failed')
	),
	provider_message_id TEXT,
	error TEXT,
	received_at TEXT,
	sent_at TEXT,
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL,
	raw_mime_key TEXT,
	delivery_status TEXT CHECK (
		delivery_status IS NULL
		OR delivery_status IN (
			'delivered', 'deferred', 'bounced', 'failed', 'rejected', 'complained'
		)
	),
	delivery_status_at TEXT,
	classification TEXT NOT NULL DEFAULT 'accepted'
		CHECK (classification IN ('accepted', 'quarantined')),
	classification_reason TEXT,
	FOREIGN KEY (inbox_id) REFERENCES email_inboxes(id) ON DELETE SET NULL,
	FOREIGN KEY (thread_id) REFERENCES system_email_threads(id) ON DELETE SET NULL,
	FOREIGN KEY (sender_identity_id) REFERENCES email_sender_identities(id)
		ON DELETE SET NULL
);
CREATE TABLE system_email_attachments (
	id TEXT PRIMARY KEY,
	message_id TEXT NOT NULL,
	filename TEXT,
	content_type TEXT NOT NULL,
	content_id TEXT,
	disposition TEXT,
	size INTEGER NOT NULL DEFAULT 0,
	storage_kind TEXT NOT NULL CHECK (
		storage_kind IN ('raw-mime', 'external', 'unavailable')
	),
	storage_key TEXT,
	created_at TEXT NOT NULL,
	FOREIGN KEY (message_id) REFERENCES system_email_messages(id)
		ON DELETE CASCADE
);
CREATE TABLE system_email_delivery_events (
	id TEXT PRIMARY KEY,
	message_id TEXT,
	inbox_id TEXT,
	event_type TEXT NOT NULL CHECK (
		event_type IN (
			'receive_started', 'received', 'rejected', 'send_requested', 'sent',
			'failed', 'delivered', 'deferred', 'bounced', 'complained'
		)
	),
	provider TEXT NOT NULL DEFAULT 'kody',
	provider_message_id TEXT,
	provider_event_id TEXT,
	detail_json TEXT NOT NULL DEFAULT '{}',
	created_at TEXT NOT NULL,
	needs_effect_reconcile INTEGER NOT NULL DEFAULT 1
		CHECK (needs_effect_reconcile IN (0, 1)),
	usage_effect_recorded_at TEXT,
	usage_month TEXT,
	usage_bytes INTEGER,
	usage_duration_ms INTEGER,
	state TEXT CHECK (
		state IS NULL
		OR state IN (
			'pending', 'storing', 'cleaning', 'received', 'rejected',
			'orphan-cleaned'
		)
	),
	fingerprint TEXT,
	storage_lease TEXT,
	storage_lease_at TEXT,
	cleanup_lease TEXT,
	cleanup_lease_at TEXT,
	cleanup_retry_at TEXT,
	expected_attachment_count INTEGER,
	finalization_token TEXT,
	reconcile_after TEXT,
	dedupe_expires_at TEXT,
	usage_effect_suppressed_at TEXT,
	usage_started_at TEXT,
	usage_effect_retry_at TEXT,
	usage_effect_lease TEXT,
	usage_effect_lease_at TEXT,
	subscription_effect_state TEXT CHECK (
		subscription_effect_state IS NULL
		OR subscription_effect_state IN (
			'pending', 'processing', 'complete', 'dead-letter'
		)
	),
	subscription_effect_lease TEXT,
	subscription_effect_lease_at TEXT,
	subscription_effect_retry_at TEXT,
	subscription_effect_attempt_count INTEGER,
	subscription_effect_dead_letter_at TEXT,
	subscription_effect_last_error TEXT,
	updated_at TEXT,
	FOREIGN KEY (message_id) REFERENCES system_email_messages(id)
		ON DELETE SET NULL,
	FOREIGN KEY (inbox_id) REFERENCES email_inboxes(id) ON DELETE SET NULL
);
CREATE TABLE system_email_graph_authority (
	singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
	authority TEXT NOT NULL CHECK (authority = 'dedicated'),
	cutover_at TEXT NOT NULL,
	graph_mismatch_count INTEGER NOT NULL CHECK (graph_mismatch_count = 0),
	provider_link_count INTEGER NOT NULL CHECK (provider_link_count = 0)
);
