	ON users(stripe_customer_id)
	WHERE stripe_customer_id IS NOT NULL;
CREATE INDEX idx_users_deleting_at
	ON users(deleting_at)
	WHERE deleting_at IS NOT NULL;
CREATE UNIQUE INDEX idx_user_repos_user_name ON user_repos(user_id, name);
CREATE UNIQUE INDEX idx_entity_source_artifacts_push_subscriptions_repo_id
	ON entity_source_artifacts_push_subscriptions(repo_id);
CREATE INDEX idx_email_inbound_due_owners_priority_due_at
	ON email_inbound_due_owners(due_at, user_id);
